-- 인덱스 생성
CREATE INDEX idx_users_name_region ON KBPARK.USERS (USER_NAME, REGION_CODE) NOLOGGING;
CREATE INDEX idx_orders_userid_date ON KBPARK.ORDERS (USER_ID, ORDER_DATE) NOLOGGING;

-- 통계 최신화
BEGIN
  DBMS_STATS.GATHER_TABLE_STATS('KBPARK','USERS');
  DBMS_STATS.GATHER_TABLE_STATS('KBPARK','ORDERS');
END;
/

-- 튜닝된 쿼리
SELECT u.user_name, o.order_id, o.order_date
FROM users u
JOIN orders o ON u.user_id = o.user_id
WHERE u.user_name = 'User_1'
  AND u.region_code = '05'
  AND o.order_date BETWEEN TO_DATE('20240501','yyyymmdd') AND TO_DATE('20240531','yyyymmdd');

/* 인덱스 생성 */
CREATE INDEX IDX_PRODUCTS_CATID_PID ON C##SHERPA.PRODUCTS (CAT_ID, PROD_ID);
CREATE INDEX IDX_ORDERS_DATE_UIDX ON C##SHERPA.ORDERS (ORDER_DATE, USER_ID, ORDER_ID);
CREATE INDEX IDX_ORDER_ITEMS_OID_PID ON C##SHERPA.ORDER_ITEMS (ORDER_ID, PROD_ID);

/* 힌트 적용 및 원본 쿼리 */
SELECT /*+ LEADING(p o oi u) USE_NL(p o oi u) */ 
  u.region_code,
  c.cat_name,
  COUNT(DISTINCT o.order_id) AS total_orders,
  SUM(oi.quantity * p.price) AS total_sales
FROM   C##SHERPA.USERS u
JOIN   C##SHERPA.ORDERS o       ON u.user_id = o.user_id
JOIN   C##SHERPA.ORDER_ITEMS oi ON o.order_id = oi.order_id
JOIN   C##SHERPA.PRODUCTS p    ON oi.prod_id = p.prod_id
JOIN   C##SHERPA.CATEGORIES c   ON p.cat_id = c.cat_id
WHERE  o.order_date BETWEEN TO_DATE('2024-01-01','YYYY-MM-DD')
                        AND TO_DATE('2024-03-31','YYYY-MM-DD')
AND    c.cat_id = 5
GROUP BY u.region_code, c.cat_name
ORDER BY total_sales DESC;
